update public.lessons l set overview='Classify, compare, and represent real numbers. This lesson moves from the underlying idea to a repeatable method, then applies it to CET-style examples. The goal is not just to remember an answer but to explain why the method works and when it applies.

CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result.',objectives=array['Represent the given information accurately in number sense.','Select and apply the appropriate formula or property in number sense.','Show an efficient solution without skipping essential reasoning in number sense.','Check magnitude, sign, units, and reasonableness in number sense.']::text[],concept_sections='[{"title":"Foundation","body":"Classify, compare, and represent real numbers."},{"title":"Governing rule","body":"Use place value and number properties before computing."},{"title":"CET application","body":"CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result."}]'::jsonb,method_steps=array['Identify what is given and what must be found.','Rewrite the information using symbols, a table, or a labeled sketch.','Choose the property or formula that connects the known and unknown values.','Carry out one justified operation at a time and keep units consistent.','Substitute the result back or estimate to confirm that it is reasonable.']::text[],worked_examples='[{"title":"Guided example 1","passage":null,"prompt":"Which number is a factor of 24?","answer":"2","solution":"24 ÷ 2 = 12, a whole number, so 2 is a factor."},{"title":"Guided example 2","passage":null,"prompt":"Which fraction is equivalent to 12/20?","answer":"3/5","solution":"Dividing numerator and denominator by 4 gives 3/5."},{"title":"Guided example 3","passage":null,"prompt":"Which number is a factor of 72?","answer":"4","solution":"72 ÷ 4 = 18, a whole number, so 4 is a factor."}]'::jsonb,common_mistakes=array['Starting computation before identifying the required quantity.','Applying a memorized formula to the wrong relationship.','Dropping a negative sign, unit, exponent, or grouping symbol.','Accepting an answer without checking it against the original conditions.']::text[],exam_tips=array['Estimate before solving so unreasonable options are easier to eliminate.','Write one clean intermediate line for multi-step calculations.','Use answer choices strategically, but still verify the governing method.','Return to skipped hard items after securing faster questions.']::text[],quick_checks='[{"prompt":"Which fraction is equivalent to 30/42?","answer":"5/7","explanation":"Dividing numerator and denominator by 6 gives 5/7."},{"prompt":"Which number is a factor of 144?","answer":"6","explanation":"144 ÷ 6 = 24, a whole number, so 6 is a factor."},{"prompt":"Which fraction is equivalent to 21/27?","answer":"7/9","explanation":"Dividing numerator and denominator by 3 gives 7/9."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='number-sense' and s.slug='mathematics';
update public.lessons l set overview='Apply operations accurately to integers, fractions, and decimals. This lesson moves from the underlying idea to a repeatable method, then applies it to CET-style examples. The goal is not just to remember an answer but to explain why the method works and when it applies.

CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result.',objectives=array['Represent the given information accurately in arithmetic operations.','Select and apply the appropriate formula or property in arithmetic operations.','Show an efficient solution without skipping essential reasoning in arithmetic operations.','Check magnitude, sign, units, and reasonableness in arithmetic operations.']::text[],concept_sections='[{"title":"Foundation","body":"Apply operations accurately to integers, fractions, and decimals."},{"title":"Governing rule","body":"Follow grouping symbols, exponents, multiplication or division, then addition or subtraction."},{"title":"CET application","body":"CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result."}]'::jsonb,method_steps=array['Identify what is given and what must be found.','Rewrite the information using symbols, a table, or a labeled sketch.','Choose the property or formula that connects the known and unknown values.','Carry out one justified operation at a time and keep units consistent.','Substitute the result back or estimate to confirm that it is reasonable.']::text[],worked_examples='[{"title":"Guided example 1","passage":null,"prompt":"Evaluate 4 + 2 × 3.","answer":"10","solution":"Multiply first: 2 × 3 = 6; then add 4 to get 10."},{"title":"Guided example 2","passage":null,"prompt":"Evaluate 5 + 3 × 4.","answer":"17","solution":"Multiply first: 3 × 4 = 12; then add 5 to get 17."},{"title":"Guided example 3","passage":null,"prompt":"Evaluate 6 + 4 × 5.","answer":"26","solution":"Multiply first: 4 × 5 = 20; then add 6 to get 26."}]'::jsonb,common_mistakes=array['Starting computation before identifying the required quantity.','Applying a memorized formula to the wrong relationship.','Dropping a negative sign, unit, exponent, or grouping symbol.','Accepting an answer without checking it against the original conditions.']::text[],exam_tips=array['Estimate before solving so unreasonable options are easier to eliminate.','Write one clean intermediate line for multi-step calculations.','Use answer choices strategically, but still verify the governing method.','Return to skipped hard items after securing faster questions.']::text[],quick_checks='[{"prompt":"Evaluate 7 + 5 × 6.","answer":"37","explanation":"Multiply first: 5 × 6 = 30; then add 7 to get 37."},{"prompt":"Evaluate 8 + 6 × 7.","answer":"50","explanation":"Multiply first: 6 × 7 = 42; then add 8 to get 50."},{"prompt":"Evaluate 9 + 7 × 3.","answer":"30","explanation":"Multiply first: 7 × 3 = 21; then add 9 to get 30."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='arithmetic-operations' and s.slug='mathematics';
update public.lessons l set overview='Model part-to-part and part-to-whole relationships. This lesson moves from the underlying idea to a repeatable method, then applies it to CET-style examples. The goal is not just to remember an answer but to explain why the method works and when it applies.

CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result.',objectives=array['Represent the given information accurately in ratios, proportions, and percentages.','Select and apply the appropriate formula or property in ratios, proportions, and percentages.','Show an efficient solution without skipping essential reasoning in ratios, proportions, and percentages.','Check magnitude, sign, units, and reasonableness in ratios, proportions, and percentages.']::text[],concept_sections='[{"title":"Foundation","body":"Model part-to-part and part-to-whole relationships."},{"title":"Governing rule","body":"A percent is a ratio with denominator 100."},{"title":"CET application","body":"CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result."}]'::jsonb,method_steps=array['Identify what is given and what must be found.','Rewrite the information using symbols, a table, or a labeled sketch.','Choose the property or formula that connects the known and unknown values.','Carry out one justified operation at a time and keep units consistent.','Substitute the result back or estimate to confirm that it is reasonable.']::text[],worked_examples='[{"title":"Guided example 1","passage":null,"prompt":"What is 10% of 40?","answer":"4","solution":"10% = 0.1. Multiplying by 40 gives 4."},{"title":"Guided example 2","passage":null,"prompt":"What is 15% of 60?","answer":"9","solution":"15% = 0.15. Multiplying by 60 gives 9."},{"title":"Guided example 3","passage":null,"prompt":"What is 20% of 80?","answer":"16","solution":"20% = 0.2. Multiplying by 80 gives 16."}]'::jsonb,common_mistakes=array['Starting computation before identifying the required quantity.','Applying a memorized formula to the wrong relationship.','Dropping a negative sign, unit, exponent, or grouping symbol.','Accepting an answer without checking it against the original conditions.']::text[],exam_tips=array['Estimate before solving so unreasonable options are easier to eliminate.','Write one clean intermediate line for multi-step calculations.','Use answer choices strategically, but still verify the governing method.','Return to skipped hard items after securing faster questions.']::text[],quick_checks='[{"prompt":"What is 25% of 100?","answer":"25","explanation":"25% = 0.25. Multiplying by 100 gives 25."},{"prompt":"What is 30% of 120?","answer":"36","explanation":"30% = 0.3. Multiplying by 120 gives 36."},{"prompt":"What is 10% of 140?","answer":"14","explanation":"10% = 0.1. Multiplying by 140 gives 14."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='ratios-percentages' and s.slug='mathematics';
update public.lessons l set overview='Solve and interpret one-variable linear relationships. This lesson moves from the underlying idea to a repeatable method, then applies it to CET-style examples. The goal is not just to remember an answer but to explain why the method works and when it applies.

CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result.',objectives=array['Represent the given information accurately in linear equations and inequalities.','Select and apply the appropriate formula or property in linear equations and inequalities.','Show an efficient solution without skipping essential reasoning in linear equations and inequalities.','Check magnitude, sign, units, and reasonableness in linear equations and inequalities.']::text[],concept_sections='[{"title":"Foundation","body":"Solve and interpret one-variable linear relationships."},{"title":"Governing rule","body":"Perform the same valid operation on both sides."},{"title":"CET application","body":"CET items usually combine the basic rule with an unfamiliar-looking expression, diagram, or word problem. The reliable approach is to translate the information, choose the governing relationship, solve carefully, and check the result."}]'::jsonb,method_steps=array['Identify what is given and what must be found.','Rewrite the information using symbols, a table, or a labeled sketch.','Choose the property or formula that connects the known and unknown values.','Carry out one justified operation at a time and keep units consistent.','Substitute the result back or estimate to confirm that it is reasonable.']::text[],worked_examples='[{"title":"Guided example 1","passage":null,"prompt":"Solve for x: 2x + 3 = 7.","answer":"2","solution":"Subtract 3, then divide by 2: x = (7 - 3)/2 = 2."},{"title":"Guided example 2","passage":null,"prompt":"Solve for x: 3x + 4 = 13.","answer":"3","solution":"Subtract 4, then divide by 3: x = (13 - 4)/3 = 3."},{"title":"Guided example 3","passage":null,"prompt":"Solve for x: 4x + 5 = 21.","answer":"4","solution":"Subtract 5, then divide by 4: x = (21 - 5)/4 = 4."}]'::jsonb,common_mistakes=array['Starting computation before identifying the required quantity.','Applying a memorized formula to the wrong relationship.','Dropping a negative sign, unit, exponent, or grouping symbol.','Accepting an answer without checking it against the original conditions.']::text[],exam_tips=array['Estimate before solving so unreasonable options are easier to eliminate.','Write one clean intermediate line for multi-step calculations.','Use answer choices strategically, but still verify the governing method.','Return to skipped hard items after securing faster questions.']::text[],quick_checks='[{"prompt":"Solve for x: 5x + 6 = 31.","answer":"5","explanation":"Subtract 6, then divide by 5: x = (31 - 6)/5 = 5."},{"prompt":"Solve for x: 6x + 7 = 43.","answer":"6","explanation":"Subtract 7, then divide by 6: x = (43 - 7)/6 = 6."},{"prompt":"Solve for x: 7x + 3 = 52.","answer":"7","explanation":"Subtract 3, then divide by 7: x = (52 - 3)/7 = 7."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='linear-algebra' and s.slug='mathematics';
