urrent."}]'::jsonb,common_mistakes=array['Confusing related terms that operate at different levels.','Treating correlation as proof of causation.','Ignoring a controlled variable or stated experimental condition.','Choosing an absolute claim when the evidence supports only a limited conclusion.']::text[],exam_tips=array['Sketch cycles, forces, circuits, or systems when relationships are hard to track.','Pay attention to words such as increase, decrease, constant, and most directly.','Eliminate choices that violate conservation, structure–function, or fair-test principles.','Use units and direction to check physics and chemistry calculations.']::text[],quick_checks='[{"prompt":"Which term means “a material in which charges move readily”?","answer":"conductor","explanation":"conductor is a material in which charges move readily."},{"prompt":"Which term means “a material that resists charge flow”?","answer":"insulator","explanation":"insulator is a material that resists charge flow."},{"prompt":"Which term means “a circuit with one current path”?","answer":"series circuit","explanation":"series circuit is a circuit with one current path."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='electricity' and s.slug='science';
