update public.lessons l set overview='Match the verb with the true grammatical subject. This lesson moves from the underlying idea to a repeatable method, then applies it to CET-style examples. The goal is not just to remember an answer but to explain why the method works and when it applies.

Language-proficiency items test whether a sentence communicates a precise meaning according to standard formal English. Read the whole sentence, identify its core structure, and then examine agreement, reference, tense, modification, punctuation, and word choice.',objectives=array['Identify the grammatical structure being tested in subject–verb agreement.','Explain why one form is standard and the alternatives are not in subject–verb agreement.','Revise without changing the intended meaning in subject–verb agreement.','Use context to resolve vocabulary and usage in subject–verb agreement.']::text[],concept_sections='[{"title":"Foundation","body":"Match the verb with the true grammatical subject."},{"title":"Governing rule","body":"Ignore interrupting phrases when identifying the subject."},{"title":"CET application","body":"Language-proficiency items test whether a sentence communicates a precise meaning according to standard formal English. Read the whole sentence, identify its core structure, and then examine agreement, reference, tense, modification, punctuation, and word choice."}]'::jsonb,method_steps=array['Read the complete sentence for meaning before inspecting individual words.','Locate the subject, main verb, clauses, and modifying phrases.','Apply the specific agreement, tense, reference, or punctuation rule.','Remove choices that introduce ambiguity, redundancy, or a change in meaning.','Read the selected sentence naturally one final time.']::text[],worked_examples='[{"title":"Guided example 1","passage":null,"prompt":"Which sentence has correct subject–verb agreement? This item appears in a library notice (set 1).","answer":"the campus library opens before classes.","solution":"the campus library opens before classes. is the only choice that follows the tested rule without changing the intended meaning."},{"title":"Guided example 2","passage":null,"prompt":"Which sentence has correct subject–verb agreement? This item appears in a laboratory report (set 1).","answer":"the group of volunteers meets every Saturday.","solution":"the group of volunteers meets every Saturday. is the only choice that follows the tested rule without changing the intended meaning."},{"title":"Guided example 3","passage":null,"prompt":"Which sentence has correct subject–verb agreement? This item appears in a scholarship essay (set 1).","answer":"each applicant brings a pencil.","solution":"each applicant brings a pencil. is the only choice that follows the tested rule without changing the intended meaning."}]'::jsonb,common_mistakes=array['Matching a verb with a nearby noun instead of the true subject.','Fixing one error while introducing a different grammatical error.','Choosing an option merely because it sounds familiar.','Ignoring the surrounding context when interpreting a word or pronoun.']::text[],exam_tips=array['Temporarily remove interrupting phrases to expose the sentence core.','Compare only the portion that changes across answer choices.','Prefer clear and economical wording when several options are grammatical.','For vocabulary, substitute the proposed meaning back into the sentence.']::text[],quick_checks='[{"prompt":"Which sentence has correct subject–verb agreement? This item appears in a student editorial (set 1).","answer":"the science club organizes a fair.","explanation":"the science club organizes a fair. is the only choice that follows the tested rule without changing the intended meaning."},{"prompt":"Which sentence has correct subject–verb agreement? This item appears in a class announcement (set 1).","answer":"the set of instructions is easy to follow.","explanation":"the set of instructions is easy to follow. is the only choice that follows the tested rule without changing the intended meaning."},{"prompt":"Which sentence has correct subject–verb agreement? This item appears in a debate brief (set 1).","answer":"the debate team practices after class.","explanation":"the debate team practices after class. is the only choice that follows the tested rule without changing the intended meaning."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='subject-verb-agreement' and s.slug='english-language';
