update public.lessons l set overview='Unawain ang di-tuwiran at masining na pahayag. Hindi sapat ang pagsasaulo ng termino; kailangang makita kung paano gumagana ang tuntunin sa buong pangungusap at sa tiyak na konteksto.

Sinusukat sa bahaging ito ang malinaw at wastong paggamit ng Filipino. Unawain muna ang buong diwa, saka suriin ang kayarian, ugnayan ng mga salita, bantas, at kahulugang hinihingi ng konteksto.',objectives=array['matukoy ang tuntuning sinusukat sa pangungusap','maipaliwanag kung bakit wasto ang isang anyo','maiayos ang pahayag nang hindi binabago ang diwa','magamit ang konteksto sa pagpapakahulugan']::text[],concept_sections='[{"title":"Pangunahing diwa","body":"Unawain ang di-tuwiran at masining na pahayag."},{"title":"Mahalagang tuntunin","body":"Huwag laging literal ang pagbasa sa idyoma."},{"title":"Gamit sa pagsusulit","body":"Sinusukat sa bahaging ito ang malinaw at wastong paggamit ng Filipino. Unawain muna ang buong diwa, saka suriin ang kayarian, ugnayan ng mga salita, bantas, at kahulugang hinihingi ng konteksto."}]'::jsonb,method_steps=array['Basahin ang buong pangungusap at tukuyin ang nais nitong sabihin.','Kilalanin ang simuno, panaguri, sugnay, at salitang nag-uugnay.','Ilapat ang tuntunin sa wastong gamit, aspekto, bantas, o kayarian.','Alisin ang sagot na malabo, salungat, o nagbabago sa orihinal na diwa.','Basahin muli ang napiling sagot upang tiyakin ang linaw at natural na daloy.']::text[],worked_examples='[{"title":"Halimbawang may gabay 1","passage":null,"prompt":"Ano ang kahulugan ng “bukas-palad” sa pangungusap? Gamitin ang pamantayang Filipino para sa paunawa sa aklatan (set 1).","answer":"mapagbigay","solution":"Ang “mapagbigay” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"title":"Halimbawang may gabay 2","passage":null,"prompt":"Ano ang kahulugan ng “bukas-palad” sa pangungusap? Gamitin ang pamantayang Filipino para sa ulat sa agham (set 1).","answer":"mapagbigay","solution":"Ang “mapagbigay” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"title":"Halimbawang may gabay 3","passage":null,"prompt":"Ano ang kahulugan ng “bukas-palad” sa pangungusap? Gamitin ang pamantayang Filipino para sa sanaysay sa klase (set 1).","answer":"mapagbigay","solution":"Ang “mapagbigay” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."}]'::jsonb,common_mistakes=array['Pagpili batay lamang sa tunog at hindi sa tuntunin.','Pagpapalit ng “ng” at “nang” nang hindi sinusuri ang gamit.','Hindi pagtukoy sa malinaw na tinutukoy ng panghalip.','Literal na pagbasa sa idyoma o tayutay.']::text[],exam_tips=array['Hanapin muna ang diwa bago suriin ang maliliit na detalye.','Tingnan ang mga salitang hudyat ng sanhi, bunga, pagsalungat, at pagkakasunod.','Ihambing ang mga pagpipilian sa parehong konteksto.','Piliin ang malinaw, wasto, at pinakamatipid na pahayag.']::text[],quick_checks='[{"prompt":"Ano ang kahulugan ng “bukas-palad” sa pangungusap? Gamitin ang pamantayang Filipino para sa liham sa paaralan (set 1).","answer":"mapagbigay","explanation":"Ang “mapagbigay” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"prompt":"Ano ang kahulugan ng “bukas-palad” sa pangungusap? Gamitin ang pamantayang Filipino para sa balita sa kampus (set 1).","answer":"mapagbigay","explanation":"Ang “mapagbigay” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"prompt":"Ano ang kahulugan ng “bukas-palad” sa pangungusap? Gamitin ang pamantayang Filipino para sa panukala ng samahan (set 1).","answer":"mapagbigay","explanation":"Ang “mapagbigay” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='idyoma-tayutay' and s.slug='filipino-language';
update public.lessons l set overview='Ayusin ang pangungusap para sa linaw at kawastuhan. Hindi sapat ang pagsasaulo ng termino; kailangang makita kung paano gumagana ang tuntunin sa buong pangungusap at sa tiyak na konteksto.

Sinusukat sa bahaging ito ang malinaw at wastong paggamit ng Filipino. Unawain muna ang buong diwa, saka suriin ang kayarian, ugnayan ng mga salita, bantas, at kahulugang hinihingi ng konteksto.',objectives=array['matukoy ang tuntuning sinusukat sa pangungusap','maipaliwanag kung bakit wasto ang isang anyo','maiayos ang pahayag nang hindi binabago ang diwa','magamit ang konteksto sa pagpapakahulugan']::text[],concept_sections='[{"title":"Pangunahing diwa","body":"Ayusin ang pangungusap para sa linaw at kawastuhan."},{"title":"Mahalagang tuntunin","body":"Panatilihin ang lohikal na ugnayan ng mga ideya."},{"title":"Gamit sa pagsusulit","body":"Sinusukat sa bahaging ito ang malinaw at wastong paggamit ng Filipino. Unawain muna ang buong diwa, saka suriin ang kayarian, ugnayan ng mga salita, bantas, at kahulugang hinihingi ng konteksto."}]'::jsonb,method_steps=array['Basahin ang buong pangungusap at tukuyin ang nais nitong sabihin.','Kilalanin ang simuno, panaguri, sugnay, at salitang nag-uugnay.','Ilapat ang tuntunin sa wastong gamit, aspekto, bantas, o kayarian.','Alisin ang sagot na malabo, salungat, o nagbabago sa orihinal na diwa.','Basahin muli ang napiling sagot upang tiyakin ang linaw at natural na daloy.']::text[],worked_examples='[{"title":"Halimbawang may gabay 1","passage":null,"prompt":"Alin ang pinakamalinaw at lohikal na pangungusap? Gamitin ang pamantayang Filipino para sa paunawa sa aklatan (set 1).","answer":"Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.","solution":"Ang “Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"title":"Halimbawang may gabay 2","passage":null,"prompt":"Alin ang pinakamalinaw at lohikal na pangungusap? Gamitin ang pamantayang Filipino para sa ulat sa agham (set 1).","answer":"Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.","solution":"Ang “Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"title":"Halimbawang may gabay 3","passage":null,"prompt":"Alin ang pinakamalinaw at lohikal na pangungusap? Gamitin ang pamantayang Filipino para sa sanaysay sa klase (set 1).","answer":"Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.","solution":"Ang “Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."}]'::jsonb,common_mistakes=array['Pagpili batay lamang sa tunog at hindi sa tuntunin.','Pagpapalit ng “ng” at “nang” nang hindi sinusuri ang gamit.','Hindi pagtukoy sa malinaw na tinutukoy ng panghalip.','Literal na pagbasa sa idyoma o tayutay.']::text[],exam_tips=array['Hanapin muna ang diwa bago suriin ang maliliit na detalye.','Tingnan ang mga salitang hudyat ng sanhi, bunga, pagsalungat, at pagkakasunod.','Ihambing ang mga pagpipilian sa parehong konteksto.','Piliin ang malinaw, wasto, at pinakamatipid na pahayag.']::text[],quick_checks='[{"prompt":"Alin ang pinakamalinaw at lohikal na pangungusap? Gamitin ang pamantayang Filipino para sa liham sa paaralan (set 1).","answer":"Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.","explanation":"Ang “Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"prompt":"Alin ang pinakamalinaw at lohikal na pangungusap? Gamitin ang pamantayang Filipino para sa balita sa kampus (set 1).","answer":"Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.","explanation":"Ang “Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."},{"prompt":"Alin ang pinakamalinaw at lohikal na pangungusap? Gamitin ang pamantayang Filipino para sa panukala ng samahan (set 1).","answer":"Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.","explanation":"Ang “Dahil nagsanay siya araw-araw, mahusay siyang tumugtog.” ang wastong sagot batay sa tuntunin at diwa ng pangungusap."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='pagwawasto' and s.slug='filipino-language';
update public.lessons l set overview='Identify the central claim without overgeneralizing. This lesson moves from the underlying idea to a repeatable method, then applies it to CET-style examples. The goal is not just to remember an answer but to explain why the method works and when it applies.

Reading questions are evidence tasks. A defensible answer must match the passage’s actual scope, wording, and purpose—not merely something that could be true outside the text.',objectives=array['State the central idea at the correct level of scope in main idea and summary.','Locate evidence for explicit and inferred claims in main idea and summary.','Analyze tone, purpose, structure, and context in main idea and summary.','Synthesize prose with tables or a second text in main idea and summary.']::text[],concept_sections='[{"title":"Foundation","body":"Identify the central claim without overgeneralizing."},{"title":"Governing rule","body":"A good summary includes the core idea and omits minor detail."},{"title":"CET application","body":"Reading questions are evidence tasks. A defensible answer must match the passage’s actual scope, wording, and purpose—not merely something that could be true outside the text."}]'::jsonb,method_steps=array['Preview the question so you know what evidence to track.','Read the passage for its claim, structure, and changes in direction.','Mark the sentence or data point that supports each possible answer.','Reject choices that are unsupported, too broad, too narrow, or reversed.','Restate the winning answer in your own words and compare it with the text.']::text[],worked_examples='[{"title":"Guided example 1","passage":"A barangay library extended its hours during examination week. Attendance rose most on evenings when volunteer tutors were present. The librarian plans to keep two evening schedules each week.","prompt":"Which statement best summarizes the passage?","answer":"Evening access paired with tutoring increased library use.","solution":"The answer stays within the evidence: Evening access paired with tutoring increased library use."},{"title":"Guided example 2","passage":"Mangrove roots slow coastal water and trap sediment. Communities that restored mangroves recorded less erosion during ordinary storms, though the trees did not eliminate all flood risk.","prompt":"Which statement best summarizes the passage?","answer":"Mangrove restoration can reduce erosion but is not complete flood protection.","solution":"The answer stays within the evidence: Mangrove restoration can reduce erosion but is not complete flood protection."},{"title":"Guided example 3","passage":"A school replaced disposable cups with refill stations. Plastic waste fell, but water use rose slightly because the stations required daily cleaning.","prompt":"Which statement best summarizes the passage?","answer":"The refill program reduced plastic while creating a smaller water-use tradeoff.","solution":"The answer stays within the evidence: The refill program reduced plastic while creating a smaller water-use tradeoff."}]'::jsonb,common_mistakes=array['Selecting a true statement that does not answer the question.','Using personal knowledge instead of passage evidence.','Treating one detail as the main idea of the entire passage.','Choosing extreme language when the author uses qualified language.']::text[],exam_tips=array['Return to the relevant lines instead of relying on memory.','Watch contrast signals such as however, although, and but.','For inference, choose what must or most reasonably follows.','Check axes, units, legends, and time periods in visual information.']::text[],quick_checks='[{"prompt":"Which statement best summarizes the passage?","answer":"The better variety depends on the expected water conditions.","explanation":"The answer stays within the evidence: The better variety depends on the expected water conditions."},{"prompt":"Which statement best summarizes the passage?","answer":"Protected lanes increased cycling without substantially delaying buses.","explanation":"The answer stays within the evidence: Protected lanes increased cycling without substantially delaying buses."},{"prompt":"Which statement best summarizes the passage?","answer":"Spaced review improved recall in the described comparison.","explanation":"The answer stays within the evidence: Spaced review improved recall in the described comparison."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='main-idea' and s.slug='reading-comprehension';
update public.lessons l set overview='Select details that directly support a claim. This lesson moves from the underlying idea to a repeatable method, then applies it to CET-style examples. The goal is not just to remember an answer but to explain why the method works and when it applies.

Reading questions are evidence tasks. A defensible answer must match the passage’s actual scope, wording, and purpose—not merely something that could be true outside the text.',objectives=array['State the central idea at the correct level of scope in supporting evidence.','Locate evidence for explicit and inferred claims in supporting evidence.','Analyze tone, purpose, structure, and context in supporting evidence.','Synthesize prose with tables or a second text in supporting evidence.']::text[],concept_sections='[{"title":"Foundation","body":"Select details that directly support a claim."},{"title":"Governing rule","body":"Strong evidence is relevant and sufficient."},{"title":"CET application","body":"Reading questions are evidence tasks. A defensible answer must match the passage’s actual scope, wording, and purpose—not merely something that could be true outside the text."}]'::jsonb,method_steps=array['Preview the question so you know what evidence to track.','Read the passage for its claim, structure, and changes in direction.','Mark the sentence or data point that supports each possible answer.','Reject choices that are unsupported, too broad, too narrow, or reversed.','Restate the winning answer in your own words and compare it with the text.']::text[],worked_examples='[{"title":"Guided example 1","passage":"A barangay library extended its hours during examination week. Attendance rose most on evenings when volunteer tutors were present. The librarian plans to keep two evening schedules each week.","prompt":"Which detail most directly supports the passage’s main conclusion?","answer":"Attendance rose most on evenings when volunteer tutors were present","solution":"The answer stays within the evidence: Evening access paired with tutoring increased library use."},{"title":"Guided example 2","passage":"Mangrove roots slow coastal water and trap sediment. Communities that restored mangroves recorded less erosion during ordinary storms, though the trees did not eliminate all flood risk.","prompt":"Which detail most directly supports the passage’s main conclusion?","answer":"Communities that restored mangroves recorded less erosion during ordinary storms, though the trees did not eliminate all flood risk","solution":"The answer stays within the evidence: Mangrove restoration can reduce erosion but is not complete flood protection."},{"title":"Guided example 3","passage":"A school replaced disposable cups with refill stations. Plastic waste fell, but water use rose slightly because the stations required daily cleaning.","prompt":"Which detail most directly supports the passage’s main conclusion?","answer":"Plastic waste fell, but water use rose slightly because the stations required daily cleaning","solution":"The answer stays within the evidence: The refill program reduced plastic while creating a smaller water-use tradeoff."}]'::jsonb,common_mistakes=array['Selecting a true statement that does not answer the question.','Using personal knowledge instead of passage evidence.','Treating one detail as the main idea of the entire passage.','Choosing extreme language when the author uses qualified language.']::text[],exam_tips=array['Return to the relevant lines instead of relying on memory.','Watch contrast signals such as however, although, and but.','For inference, choose what must or most reasonably follows.','Check axes, units, legends, and time periods in visual information.']::text[],quick_checks='[{"prompt":"Which detail most directly supports the passage’s main conclusion?","answer":"Variety A yielded more during dry weeks; Variety B recovered faster after flooding","explanation":"The answer stays within the evidence: The better variety depends on the expected water conditions."},{"prompt":"Which detail most directly supports the passage’s main conclusion?","answer":"Bicycle counts increased, while travel time for buses changed little during the trial","explanation":"The answer stays within the evidence: Protected lanes increased cycling without substantially delaying buses."},{"prompt":"Which detail most directly supports the passage’s main conclusion?","answer":"Students who spaced four short review sessions across a week recalled more terms than students who studied once for the same total time","explanation":"The answer stays within the evidence: Spaced review improved recall in the described comparison."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='supporting-evidence' and s.slug='reading-comprehension';
