e evidence: Spaced review improved recall in the described comparison."}]'::jsonb,source_links='[{"title":"DepEd Strengthened Senior High School Program","url":"https://www.deped.gov.ph/strengthened-shs-program/"},{"title":"UPCAT official site","url":"https://upcat.up.edu.ph/"},{"title":"USTET official site","url":"https://ustet.ust.edu.ph/"}]'::jsonb,estimated_minutes=20,status='published' from public.topics t join public.subjects s on s.id=t.subject_id where l.topic_id=t.id and t.slug='inference' and s.slug='reading-comprehension';
